//! 🏛️ Admitted Model spatial placements, complete classes, typed properties and relations.
use crate::standards::v1::subsets::base::schema::geometry::{SemioTransform,SemioPoint3,SemioQuaternion};
use crate::standards::v1::subsets::model::schema::snapshot::{SemioModelSnapshot,SpatialNode,SpatialKind,SemioModelElement,ElementClass,GeometryRef,PropertySet,Property,PsetValue,ModelRelation,RelationKind,STDIO_SEMIOMODEL_DOCUMENT_SCHEMA};
